// ============================================================================
// UALink_apb: APB4 register wrapper around UALink_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/UALink.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/UALink.md
// ============================================================================
module UALink_apb #(
  parameter int MW = 16,
  parameter int RQ = 4,
  parameter int DQ = 8
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  input logic req_valid,
  input logic [2:0] req_cmd,
  input logic [7:0] req_tag,
  input logic [15:0] req_addr,
  input logic [2:0] req_len,
  output logic req_crd,
  input logic od_valid,
  input logic [63:0] od_data,
  input logic [7:0] od_be,
  input logic od_last,
  output logic od_crd,
  output logic rd_valid,
  output logic [7:0] rd_tag,
  output logic [63:0] rd_data,
  output logic rd_last,
  output logic [1:0] rd_status,
  input logic rd_crd,
  output logic wr_valid,
  output logic [7:0] wr_tag,
  output logic [1:0] wr_status,
  input logic wr_crd
);
  localparam logic [31:0] ID_VALUE = 32'h554C0200;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [4:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd5) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic          c_ev_err;
  logic          c_ev_proto;
  UALink_top #(.MW(MW), .RQ(RQ), .DQ(DQ)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .req_valid(req_valid),
    .req_cmd(req_cmd),
    .req_tag(req_tag),
    .req_addr(req_addr),
    .req_len(req_len),
    .req_crd(req_crd),
    .od_valid(od_valid),
    .od_data(od_data),
    .od_be(od_be),
    .od_last(od_last),
    .od_crd(od_crd),
    .rd_valid(rd_valid),
    .rd_tag(rd_tag),
    .rd_data(rd_data),
    .rd_last(rd_last),
    .rd_status(rd_status),
    .rd_crd(rd_crd),
    .wr_valid(wr_valid),
    .wr_tag(wr_tag),
    .wr_status(wr_status),
    .wr_crd(wr_crd),
    .ev_err(c_ev_err),
    .ev_proto(c_ev_proto)
  );

  // ---------------- registers ----------------
  logic [1:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[1:0] & wmask[1:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[1:0]) | (PWDATA[1:0] & wmask[1:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
    end
  end

  // ---------------- core inputs ----------------

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_ev_err;
    irq_set[1] = c_ev_proto;
  end
  assign irq = |(irq_status & irq_enable);

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd4: apb_rdata = scratch;
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
